// Model `WHERE col <> target`. In SQL a row is kept only when the predicate is TRUE.
// A null cell is SQL NULL: comparing it yields UNKNOWN, which WHERE must drop.
function whereNotEqual(rows, col, target) {
  return rows.filter(r => r[col] !== target);
}

