// rows: parsed CSV objects {sku, name, tags, price}
function toRelation(rows) {
  const seen = new Set();
  const out = [];
  for (const r of rows) {
    // dedup by name so we don't store the 'same' product twice
    if (seen.has(r.name)) continue;
    seen.add(r.name);
    out.push({
      sku: r.sku,
      name: r.name,
      tags: r.tags,            // e.g. 'sale,clearance,new'
      price: r.price,
    });
  }
  return out;
}

